-- Local development seed; first run: alembic upgrade head
-- psql 'postgresql://USER:PASSWORD@localhost:5432/articles' -v ON_ERROR_STOP=1 -f scripts/seed.sql
-- All real primary keys are generated by PostgreSQL. Existing rows are not overwritten.
BEGIN;

INSERT INTO tenants (name)
SELECT seed.name FROM (VALUES ('Acme Tenant'), ('Globex Tenant'), ('Initech Tenant')) AS seed(name)
WHERE NOT EXISTS (SELECT 1 FROM tenants t WHERE t.name = seed.name);

-- Logical keys are only for this seed file; they are not database tenant IDs.
CREATE TEMP TABLE seed_tenants ON COMMIT DROP AS
SELECT seed.tenant_key, MIN(t.id) AS tenant_id
FROM (VALUES (1, 'Acme Tenant'), (2, 'Globex Tenant'), (3, 'Initech Tenant')) AS seed(tenant_key, name)
JOIN tenants t ON t.name = seed.name
GROUP BY seed.tenant_key;

SELECT setval(
    pg_get_serial_sequence('code_master', 'id'),
    COALESCE((SELECT MAX(id) FROM code_master), 1),
    EXISTS (SELECT 1 FROM code_master)
);

INSERT INTO code_master (group_name, value) VALUES
    ('article_status', 'Pending'),
    ('article_status', 'Processing'),
    ('article_status', 'Completed'),
    ('article_status', 'Failed')
ON CONFLICT (group_name, value) DO NOTHING;

INSERT INTO companies (tenant_id, name)
SELECT t.tenant_id, seed.name
FROM (VALUES (1, 'Acme Labs'), (1, 'Acme Media'),
             (2, 'Globex Research'), (3, 'Initech Systems')) AS seed(tenant_key, name)
JOIN seed_tenants t ON t.tenant_key = seed.tenant_key
ON CONFLICT (tenant_id, name) DO NOTHING;

CREATE TEMP TABLE seed_articles (
    seed_key INTEGER PRIMARY KEY,
    tenant_key INTEGER NOT NULL,
    company_name VARCHAR(255) NOT NULL,
    title VARCHAR(500) NOT NULL,
    url VARCHAR(2048) NOT NULL,
    status VARCHAR(64) NOT NULL,
    category VARCHAR(128)
) ON COMMIT DROP;

INSERT INTO seed_articles (seed_key, tenant_key, company_name, title, url, status, category) VALUES
    (1, 1, 'Acme Labs', 'Acme research update',
     'https://example.com/acme/research', 'Pending', 'Research'),
    (2, 1, 'Acme Labs', 'Acme platform launch',
     'https://example.com/acme/platform', 'Processing', 'Technology'),
    (3, 1, 'Acme Media', 'Acme quarterly news',
     'https://example.com/acme/news', 'Completed', 'Business'),
    (4, 2, 'Globex Research', 'Globex study results',
     'https://example.com/globex/study', 'Completed', 'Research'),
    (5, 2, 'Globex Research', 'Globex market analysis',
     'https://example.com/globex/market', 'Failed', 'Business'),
    (6, 2, 'Globex Research', 'Globex product preview',
     'https://example.com/globex/product', 'Pending', 'Technology'),
    (7, 3, 'Initech Systems', 'Initech release notes',
     'https://example.com/initech/release', 'Processing', 'Technology'),
    (8, 3, 'Initech Systems', 'Initech hiring update',
     'https://example.com/initech/hiring', 'Completed', NULL),
    (9, 3, 'Initech Systems', 'Initech service report',
     'https://example.com/initech/service', 'Failed', 'Operations');

INSERT INTO articles (company_id, title, url, content, status_id, category, version)
SELECT c.id, s.title, s.url, 'Sample content for ' || s.title, cm.id, s.category, 1
FROM seed_articles s
JOIN seed_tenants t ON t.tenant_key = s.tenant_key
JOIN companies c ON c.tenant_id = t.tenant_id AND c.name = s.company_name
JOIN code_master cm ON cm.group_name = 'article_status' AND cm.value = s.status
ORDER BY s.seed_key
ON CONFLICT (url) DO NOTHING;

INSERT INTO tenant_articles (tenant_id, article_id)
SELECT t.tenant_id, a.id
FROM seed_articles s
JOIN seed_tenants t ON t.tenant_key = s.tenant_key
JOIN articles a ON a.url = s.url
JOIN companies c ON c.id = a.company_id
                AND c.tenant_id = t.tenant_id AND c.name = s.company_name
ON CONFLICT DO NOTHING;

-- Inspect generated IDs to use in POST payloads and GET headers/cursors.
SELECT t.id AS tenant_id, t.name AS tenant_name, a.id AS article_id,
       c.id AS company_id, c.name AS company_name, a.title, cm.value AS status
FROM seed_tenants st
JOIN tenants t ON t.id = st.tenant_id
JOIN tenant_articles ta ON ta.tenant_id = t.id
JOIN articles a ON a.id = ta.article_id
JOIN companies c ON c.id = a.company_id
JOIN code_master cm ON cm.id = a.status_id
ORDER BY t.id, a.id;

COMMIT;
